name: Auto‑approve workflows for returning contributors and ok‑to‑test labeled PRs

on:
  pull_request:
    types: [labeled, synchronize]

jobs:
  approve:
    if: github.event.pull_request.head.repo.full_name == github.repository
    runs-on: ubuntu-latest
    permissions:
      actions: write
      workflow: write
      pull-requests: read
    steps:
      - name: Auto‑approve pending workflow runs
        uses: actions/github-script@v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr = context.payload.pull_request;
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const headBranch = pr.head.ref;
            const creator = pr.user.login;

            // Check if the PR has the ok‑to‑test label
            const okToTest = pr.labels.some(label => label.name === 'ok-to-test');

            // Count all PRs created by this contributor
            const pulls = await github.pulls.list({
              owner,
              repo,
              creator,
              state: 'all',
              per_page: 100
            });
            const totalPRs = pulls.data.length;
            const isFirstTime = totalPRs <= 1;

            if (!okToTest && isFirstTime) {
              console.log('First‑time contributor without ok‑to‑test label. Skipping approval.');
              return;
            }

            // Find pending workflow runs for this PR
            const runs = await github.actions.listWorkflowRunsForRepo({
              owner,
              repo,
              event: 'pull_request',
              head_branch: headBranch,
              per_page: 100
            });

            const pendingRuns = runs.data.filter(run => run.status === 'queued' && run.conclusion === null);

            for (const run of pendingRuns) {
              console.log(`Approving workflow run ${run.id} (${run.name})`);
              await github.actions.createWorkflowRunApproval({
                owner,
                repo,
                run_id: run.id
              });
            }
